      "id": "servier-medical-art",
      "name": "Servier Medical Art",
      "domains": ["anatomy", "medical", "biology"],
      "license": "CC-BY-4.0",
      "attribution": "Servier Medical Art (CC BY 4.0), in the format its credit page gives; note any changes you made.",
      "formats": ["image"],
      "access": "Download from the illustration's page; no API.",
      "urls": {
        "site": "https://smart.servier.com",
        "credit": "https://smart.servier.com/how-to-cite-servier-medical-art/"
      },
      "notes": "Organs, joints, cells and medical procedures in one flat style. Recoloring, tracing and splitting into layers are allowed with credit."
    },
    {
      "id": "nih-bioart",
      "name": "NIH BioArt Source",
      "domains": ["biology", "medical", "lab"],
      "license": "Free for any use, including commercial; each entry may carry its own license, so check it",
      "attribution": "Illustration from NIAID NIH BioArt Source",
      "formats": ["image"],
      "access": "Download from the entry's page.",
      "urls": {
        "site": "https://bioart.niaid.nih.gov",
        "terms": "https://bioart.niaid.nih.gov/terms"
      },
      "notes": "Pathogens, cells, lab equipment and anatomy icons."
    },
    {
      "id": "wikimedia-commons",
      "name": "Wikimedia Commons",
      "domains": ["anatomy", "science", "diagrams", "maps", "landmarks", "species", "history"],
      "license": "Per file (public domain, CC BY, CC BY-SA and others); read each file's page",
      "attribution": "As the file's license states; credit the original author, not the uploader.",
      "formats": ["svg", "png", "jpg"],
      "access": "Public MediaWiki API, no key; send a descriptive User-Agent and make requests one at a time.",
      "urls": {
        "site": "https://commons.wikimedia.org",
        "reuse": "https://commons.wikimedia.org/wiki/Commons:Reusing_content_outside_Wikimedia",
        "api": "https://commons.wikimedia.org/w/api.php"
      },
      "notes": "Many anatomy and science diagrams are SVG, which can be split into parts to animate. CC BY-SA requires the same license on an edited image you redistribute."
    }
  ]
}
